import re


def slugify(text):
    text = text.strip().lower()
    # Remove all non-alphanumeric characters except space, then replace spaces with dashes
    result = re.sub(r'[^a-z0-9\s]+', '', text)
    return result.replace(' ', '-')


def truncate(text, n):
    if len(text) <= n:
        return text
    return text[: n - 3] + "..."
EOF
